ALTER TABLE data ADD COLUMN extended_timeline BOOLEAN;
UPDATE data SET extended_timeline = CASE 
    WHEN closed_at IS NOT NULL AND CAST(closed_at AS DATE) >= CAST(opened_at AS DATE) 
    AND (CAST(closed_at AS DATE) - CAST(opened_at AS DATE)) > 250 THEN TRUE 
    ELSE FALSE 
END;
